            document.getElementById('info-degree').innerHTML = `
                &lt;strong&gt;Conceito:&lt;/strong&gt; Mede o número de conexões diretas do nó.&lt;br&gt;
                &lt;span class="formula"&gt;C_D(v) = degree(v)&lt;/span&gt;&lt;br&gt;
                &lt;em&gt;Clique nos botões ou em um nó para visualizar os vizinhos.&lt;/em&gt;
