        }

        // Closeness Logic
        function calcCloseness(nodeId) {
            resetCloseness();
            const distances = {
                'D': { A: 2, B: 1, C: 1, E: 1, F: 1, sum: 6, score: (5/6).toFixed(2) },
                'A': { B: 1, C: 1, D: 2, E: 3, F: 3, sum: 10, score: (5/10).toFixed(2) }
            }[nodeId];

            document.querySelector(`#svg-closeness .cn-${nodeId}`).classList.add('target-closeness');

            document.getElementById('info-closeness').innerHTML = `
                &lt;strong style="color:var(--accent-green)"&gt;Calculando para o Nó ${nodeId}:&lt;/strong&gt;&lt;br&gt;
                Soma das distâncias = ${distances.sum} | Nº de outros nós = 5&lt;br&gt;
                &lt;span class="formula"&gt;C_C(${nodeId}) = 5 / ${distances.sum} = ${distances.score}&lt;/span&gt;
            `;
        }

        function resetCloseness() {
            document.querySelectorAll('#svg-closeness .node').forEach(n =&gt; n.classList.remove('target-closeness'));
            document.getElementById('info-closeness').innerHTML = `
                &lt;strong&gt;Conceito:&lt;/strong&gt; Inverso da soma das distâncias mais curtas para todos os outros nós.&lt;br&gt;
                &lt;span class="formula"&gt;C_C(u) = (N - 1) / Σ d(u, v)&lt;/span&gt;&lt;br&gt;
                &lt;em&gt;Nós centrais chegam mais rápido a toda a rede.&lt;/em&gt;
            `;
        }

        // Betweenness Logic
        function simBetweenness(start, end) {
            resetBetweenness();
            if (start === 'A' && end === 'E') {
                document.querySelectorAll('.bn-AC, .bn-CD, .bn-DE').forEach(e =&gt; e.classList.add('highlight-path'));
                document.querySelectorAll('.bn-node-A, .bn-node-C, .bn-node-D, .bn-node-E').forEach(n =&gt; n.classList.add('between-path'));
                document.getElementById('info-betweenness').innerHTML = `
                    &lt;strong style="color:var(--accent-amber)"&gt;Caminho Mínimo A → E:&lt;/strong&gt; A → C → D → E&lt;br&gt;
                    Os nós &lt;strong&gt;C&lt;/strong&gt; e &lt;strong&gt;D&lt;/strong&gt; atuam como intermediadores essenciais nesta rota.&lt;br&gt;
                    &lt;span class="formula"&gt;+1 ponto de intermediação para C e D&lt;/span&gt;
                `;
            } else if (start === 'A' && end === 'F') {
                document.querySelectorAll('.bn-AC, .bn-CD, .bn-DF').forEach(e =&gt; e.classList.add('highlight-path'));
                document.querySelectorAll('.bn-node-A, .bn-node-C, .bn-node-D, .bn-node-F').forEach(n =&gt; n.classList.add('between-path'));
                document.getElementById('info-betweenness').innerHTML = `
                    &lt;strong style="color:var(--accent-amber)"&gt;Caminho Mínimo A → F:&lt;/strong&gt; A → C → D → F&lt;br&gt;
                    O nó &lt;strong&gt;D&lt;/strong&gt; é o ponto de passagem obrigatório (gargalo) para alcançar F.&lt;br&gt;
                    &lt;span class="formula"&gt;Nó D possui a maior Betweenness da rede&lt;/span&gt;
                `;
            }
        }

        function resetBetweenness() {
            document.querySelectorAll('#svg-betweenness .edge').forEach(e =&gt; e.classList.remove('highlight-path'));
            document.querySelectorAll('#svg-betweenness .node').forEach(n =&gt; n.classList.remove('between-path'));
            document.getElementById('info-betweenness').innerHTML = `
                &lt;strong&gt;Conceito:&lt;/strong&gt; Mede quantas vezes o nó atua como ponte no menor caminho entre pares.&lt;br&gt;
                &lt;span class="formula"&gt;C_B(v) = Σ (σ_st(v) / σ_st)&lt;/span&gt;&lt;br&gt;
                &lt;em&gt;Nós como D têm alto poder de ponte (bridge).&lt;/em&gt;
            `;
        }

        // Eigenvector Logic
        function showEigenScores() {
            document.getElementById('info-eigen').innerHTML = `
                &lt;strong style="color:var(--accent-purple)"&gt;Valores de Autovetor Estimados:&lt;/strong&gt;&lt;br&gt;
                D: &lt;strong&gt;0.62&lt;/strong&gt; (Conectado aos nós mais importantes)&lt;br&gt;
                B: 0.48 | C: 0.48 | A: 0.28 | E: 0.18 | F: 0.18&lt;br&gt;
                &lt;span class="formula"&gt;Centralidade é "herdada" da centralidade dos vizinhos.&lt;/span&gt;
            `;
        }

        function resetEigen() {
            document.getElementById('info-eigen').innerHTML = `
                &lt;strong&gt;Conceito:&lt;/strong&gt; A importância de um nó é proporcional à importância de seus vizinhos.&lt;br&gt;
                &lt;span class="formula"&gt;λ · x_i = Σ A_ij · x_j&lt;/span&gt;&lt;br&gt;
                &lt;em&gt;E e F têm mesmo grau que A, mas menor autovetor porque se ligam a vizinhos menos conectados.&lt;/em&gt;
            `;
        }
